-- 61 Firefly Glade: the fireflies, the sparkler and the shooting stars are
-- particle emitters with trails (`trail`); this carries the sparkler, sends a
-- shooting star now and then (Space for one now) and takes the trails away
-- with T. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/61-firefly-glade.scene"
local TRAILS = {
    Fireflies = { length = 16, interval = 0.06, width = 0.8, taper = true, fade = true },
    PondFlies = { length = 16, interval = 0.06, width = 0.8, taper = true, fade = true },
    Sparkler = { length = 6, interval = 0.025, width = 0.9, taper = true, fade = true },
    Meteor = { length = 16, interval = 0.02, width = 0.7, taper = true, fade = true },
}
local captions = true
local on = true
local emitters = {}
local sparkler, glow, meteor, status
local t, next_star = 0, 2.0

function init(entity)
    status = Entity.find_by_name("Status")
    for name, _ in pairs(TRAILS) do emitters[name] = Entity.find_by_name(name) end
    sparkler = emitters.Sparkler
    glow = Entity.find_by_name("SparklerGlow")
    meteor = emitters.Meteor
end

local function shooting_star()
    if not meteor then return end
    Transform.set_position(meteor, -200 + math.random() * 800, 280 + math.random() * 60)
    Particles.emit_burst(meteor, 1)
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    local mx, my = Input.get_mouse_world_position()
    if mx then
        if sparkler then Transform.set_position(sparkler, mx, my) end
        if glow then Transform.set_position(glow, mx, my) end
    end
    t = t + dt
    if Input.is_key_just_pressed("Space") or t > next_star then
        shooting_star()
        next_star = t + 5 + math.random() * 6
    end
    if Input.is_key_just_pressed("T") then
        on = not on
        for name, e in pairs(emitters) do
            if e then Particles.set(e, "trail", on and TRAILS[name] or nil) end
        end
    end
    if status then UI.set_text(status, on and "every spark and firefly draws where it has been" or "trails off") end
end
